B_{i,j} + pt_{i,j,k}X_{i,j,k}
\leq B_{i',j'} + M\left(3-Y_{i,j,i',j'}-X_{i,j,k}-X_{i',j',k}\right)
\end{equation}
\begin{equation}
B_{i',j'} + pt_{i',j',k}X_{i',j',k}
\leq B_{i,j} + M\left(2+Y_{i,j,i',j'}-X_{i,j,k}-X_{i',j',k}\right),
\quad \forall i<i',\ j \in J_i,\ j' \in J_{i'},\ k \in K_{i,j}\cap K_{i',j'}
\end{equation}#(约束3)
\begin{equation}
B_{i,j} + \sum_{k \in K_{i,j}} pt_{i,j,k}X_{i,j,k}
\leq C_{\max},
\quad \forall i \in I,\ j \in J_i
\end{equation}#(约束4)
\begin{equation}
B_{i,j} \geq 0,
\quad \forall i \in I,\ j \in J_i
\end{equation}#(约束5)
\begin{equation}B_{i,j} \geq 51 X_{i,j,1} \\ \forall i\in I,j\in J_i\end{equation}#(约束6)

